def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the uniform separator column.
    columns = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep = min(columns, key=lambda c: abs(c - (w - 1) / 2))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    out_w = min(len(left[0]), len(right[0]))
    lc = Counter(v for row in left for v in row)
    rc = Counter(v for row in right for v in row)
    lbg, rbg = lc.most_common(1)[0][0], rc.most_common(1)[0][0]
    lfg = next(v for v in lc if v != lbg)
    rfg = next(v for v in rc if v != rbg)
    if lfg == rfg:
        # Keep left pattern blank cells as 8; overlapping marks convert to 3.
        out = [[8 for _ in range(out_w)] for _ in range(h)]
        for r in range(h):
            for c in range(out_w):
                if left[r][c] == lbg and right[r][c] == rbg:
                    out[r][c] = 3
    else:
        # Keep positions blank in both panels as 3, all positions carrying a
        # mark in either panel as the shared background color.
        out = [[3 for _ in range(out_w)] for _ in range(h)]
        for r in range(h):
            for c in range(out_w):
                if left[r][c] != lbg or right[r][c] != rbg:
                    out[r][c] = lbg
    return out


if __name__ == '__main__':
